/* DRAFT - This is a speculative starter for a developer. */
const choralPad = new Tone.PolySynth(Tone.FMSynth, {
  harmonicity: 1.5,
  modulationIndex: 10,
  oscillator: { type: 'sine' },
  envelope: { attack: 0.2, release: 1.5 },
  modulation: { type: 'sawtooth' },
  modulationEnvelope: { attack: 0.1, release: 1.5 },
}).toDestination();
const choralPart = new Tone.Part((time, note) => {
  choralPad.triggerAttackRelease(note, '8n', time);
}, [
  { time: '0:0', note: 'C5' },
  { time: '0:1', note: 'Bb4' },
  { time: '0:2', note: 'A4' }
]).start(0);

const screamStab = new Tone.MonoSynth({
  oscillator: { type: 'sawtooth' },
  filter: { type: 'peaking', frequency: 3000, Q: 5 },
  envelope: { attack: 0.005, decay: 0.4 },
}).chain(new Tone.Distortion(0.9), Tone.Destination);

const mainNarrator = new Tone.MonoSynth({
    oscillator: { type: 'pulse' },
    filter: { type: 'bandpass', frequency: 1500, Q: 4 },
    envelope: { attack: 0.01, decay: 0.2 }
}).chain(new Tone.BitCrusher(6), Tone.Destination);
