/* Speculative Score Draft */
// Set tempo to a slow, driving 77 BPM.
Tone.Transport.bpm.value = 77;

// Main 'Growler Bass' synth
// Use a MonoSynth with a fat oscillator for thickness and heavy drive for grit.
// A resonant lowpass filter is key to the 'growl'.
const growlerBass = new Tone.MonoSynth({
  oscillator: { type: 'fatsawtooth', count: 5, spread: 30 },
  envelope: { attack: 0.02, decay: 0.2, sustain: 0.3, release: 0.4 },
  filterEnvelope: { attack: 0.01, decay: 0.1, sustain: 0.2, release: 0.5, baseFrequency: 100, octaves: 4 },
  filter: { type: 'lowpass', Q: 4 },
  volume: -6
}).chain(new Tone.Distortion(0.7), Tone.Destination);

// Bass pattern: a syncopated 16th-note loop in E minor.
const bassPattern = new Tone.Sequence((time, note) => {
  if (note) growlerBass.triggerAttackRelease(note, '16n', time);
}, [
  'E2', null, null, 'E2', null, 'E2', 'G2', null, 'E2', null, null, 'A2', null, 'G2', 'E2', null
], '16n').start(0);

// 'Sub Kick' for intro sections.
// A driven MembraneSynth for a distorted, percussive low-end pulse.
const subKick = new Tone.MembraneSynth({
  attack: 0.01, decay: 0.4, harmonicity: 1.5, volume: -9
}).chain(new Tone.Distortion(0.4), Tone.Destination);

const kickPattern = new Tone.Sequence((time, note) => {
  subKick.triggerAttackRelease(note, '8n', time);
}, ['C1', 'C1', 'C1', 'C1'], '4n');
